package manifest_test

import (
	"encoding/json"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"testing"

	"github.com/teandresmith/sqlgen/cmd/sqlgen/config"
	"github.com/teandresmith/sqlgen/cmd/sqlgen/manifest"
)

// examplesDir is the checked-in golden tree the examples' generated output
// lives under. Regenerated by `make update-golden-e2e`.
const examplesDir = "../testdata/examples"

// TestEntityFilesExistOnDisk is the drift guard for entity files[] against
// the generated tree on disk.
//
// files[] is how a manifest reader finds the Go code an entity was generated
// into — a human, an agent through MCP §31's sqlgen_get_entity (which does not
// strip the field in compact mode), or the `## Files` section of the per-entity
// markdown. It was spelled `<snake>_gen.go` unconditionally, which is the
// `output.layout: file_per_table` name; under the default `single_file` the
// bodies are concatenated into models_gen.go / views_gen.go, so every entry in
// four of the five example trees named a path that does not exist. Nothing
// compared the claim against the filesystem, which is why it shipped.
//
// This walks the checked-in golden trees and makes exactly that comparison,
// covering both `output.layout` values and both manifest `json_layout` values
// at once: postgres / mysql are single_file + single JSON, graphql and
// tenancy_postgres are single_file + per_entity JSON, sqlite is file_per_table.
func TestEntityFilesExistOnDisk(t *testing.T) {
	manifests := findGoldenManifests(t)
	if len(manifests) == 0 {
		t.Fatalf("no manifest_gen.json found under %s — the example tree moved", examplesDir)
	}

	var checked int
	for _, m := range manifests {
		// <example>/<outputDir>/manifest/manifest_gen.json — the generated Go
		// files sit two levels up, beside the manifest directory.
		outputDir := filepath.Dir(filepath.Dir(m))
		t.Run(filepath.ToSlash(outputDir), func(t *testing.T) {
			for _, e := range goldenEntities(t, m) {
				if len(e.Files) == 0 {
					t.Errorf("entity %q carries no files[]", e.Name)
					continue
				}
				for _, f := range e.Files {
					checked++
					path := filepath.Join(outputDir, f)
					if _, err := os.Stat(path); err != nil {
						t.Errorf("entity %q names files[] entry %q, but %s does not exist",
							e.Name, f, path)
					}
				}
			}
		})
	}
	if checked == 0 {
		t.Fatal("no files[] entries were checked — the golden manifests stopped carrying the field")
	}
}

// findGoldenManifests returns every top-level manifest_gen.json in the example
// tree, sorted so failures report in a stable order. Both the `models/` output
// and its `expected/` golden twin are walked: they are separate checked-in
// copies and either can go stale on its own.
func findGoldenManifests(t *testing.T) []string {
	t.Helper()

	var found []string
	err := filepath.WalkDir(examplesDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !d.IsDir() && d.Name() == "manifest_gen.json" {
			found = append(found, path)
		}
		return nil
	})
	if err != nil {
		t.Fatalf("walking %s: %v", examplesDir, err)
	}
	slices.Sort(found)
	return found
}

// entityIndexEntry is the lightweight pointer form the per_entity JSON layout
// carries in place of full entities (PRD §30.4). Declared locally rather than
// imported: the runtime reader module's EntityIndex is the consumer-side type,
// and this package builds the other side of the same file.
type entityIndexEntry struct {
	Name string `json:"name"`
	File string `json:"file"`
}

// goldenEntities reads one manifest's entities, following the per_entity JSON
// layout out to the sibling entities/*.json files when that is the shape on
// disk — those carry their own files[] and are what MCP loads in that mode.
func goldenEntities(t *testing.T, path string) []manifest.Entity {
	t.Helper()

	var layoutProbe struct {
		Layout string `json:"layout"`
	}
	readGoldenJSON(t, path, &layoutProbe)

	if layoutProbe.Layout == string(config.JSONLayoutPerEntity) {
		var doc struct {
			Entities []entityIndexEntry `json:"entities"`
		}
		readGoldenJSON(t, path, &doc)
		if len(doc.Entities) == 0 {
			t.Fatalf("%s: per_entity manifest carries no entity index", path)
		}
		entities := make([]manifest.Entity, 0, len(doc.Entities))
		for _, idx := range doc.Entities {
			var e manifest.Entity
			readGoldenJSON(t, filepath.Join(filepath.Dir(path), idx.File), &e)
			entities = append(entities, e)
		}
		return entities
	}

	doc := new(manifest.Document)
	readGoldenJSON(t, path, doc)
	if len(doc.Entities) == 0 {
		t.Fatalf("%s: single-layout manifest carries no entities", path)
	}
	return doc.Entities
}

func readGoldenJSON(t *testing.T, path string, dst any) {
	t.Helper()

	data, err := os.ReadFile(path) //nolint:gosec // test helper, path comes from walking the checked-in testdata tree
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	if err := json.Unmarshal(data, dst); err != nil {
		t.Fatalf("decode %s: %v", path, err)
	}
}
